package sohal.lld.battleship.firing;import sohal.lld.battleship.model.Coord;import java.util.ArrayList;import java.util.List;import java.util.Random;import java.util.Set;public class RandomFireStrategy implements FireStrategy {    private final Random rnd;    public RandomFireStrategy(Random rnd) { this.rnd = rnd; }    /**     * Pick a coordinate to fire at, given the available columns x range and already fired coords.     * Implementations must return a coordinate within [xStart..xEnd] x [0..N-1] or null if none available.     *     * @param xStart     * @param xEnd     * @param n     * @param firedSoFar     */    @Override    public Coord pickTarget(int xStart, int xEnd, int n, Set<Coord> firedSoFar) {        List<Coord> available = new ArrayList<>();        for (int x = xStart; x <= xEnd; x++) for (int y = 0; y < n; y++) {            Coord c = new Coord(x, y);            if (!firedSoFar.contains(c)) available.add(c);        }        if (available.isEmpty()) return null;        return available.get(rnd.nextInt(available.size()));    }}